local _, ns = ...
local Translate = ns.Lore.Translate

Translate("frFR", "humans", {
	title = "Humains",
	sections = {
		{
			title = "Résumé",
			text = [=[Les humains sont le plus nombreux des jeunes peuples des {link:eastern-kingdoms}Royaumes de l'est{/link}. Leur vie est brève à côté de celle des elfes et des nains, mais ils sont remuants, obstinés et prompts à apprendre. De leurs lignées sont nés les grands royaumes du nord et du sud, et de leurs rangs sont venus les paladins de la {link:holy-light}Lumière sacrée{/link} et les mages de {link:dalaran}Dalaran{/link}. Ils ont souffert plus que tout autre peuple dans les guerres contre les orcs et les morts-vivants, et ils ne se sont pas encore brisés.]=],
		},
		{
			title = "Origines",
			text = [=[Dans les temps anciens, les humains vivaient en tribus éparses dans le nord, chacune se méfiant des autres. Seule la tribu des {link:arathi-highlands}Arathi{/link} comprit que l'empire {link:trolls}troll{/link} des Amani les détruirait l'une après l'autre. Leur seigneur de guerre, {link:thoradin}Thoradin{/link}, unit les tribus par la force et par la persuasion, et sur cette union il fonda la nation d'{link:arathor}Arathor{/link} et sa cité-forteresse de {link:stromgarde-keep}Strom{/link}. Quand les Amani marchèrent contre les {link:high-elves}hauts-elfes{/link} de {link:quel-thalas}Quel'Thalas{/link}, Arathor répondit à l'appel des elfes. Les elfes enseignèrent à cent humains les voies de la {link:arcane-magic}magie des arcanes{/link}, et ensemble les deux peuples brisèrent les Amani lors des {link:troll-wars}guerres des Trolls{/link}.

Dans la longue paix qui suivit, l'unité d'Arathor s'effaça. Son peuple se répandit à travers le pays et fonda de nouveaux royaumes : {link:lordaeron}Lordaeron{/link} au nord, {link:gilneas}Gilneas{/link} et {link:kul-tiras}Kul Tiras{/link} sur les côtes de l'ouest, {link:alterac-mountains}Alterac{/link} et Stromgarde dans les montagnes, la cité des mages à {link:dalaran}Dalaran{/link} et, loin au sud, le royaume d'{link:azeroth}Azeroth{/link}, que l'on appelle aujourd'hui le {link:kingdom-of-stormwind}royaume de Stormwind{/link}.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les humains sont un peuple de rois et de paysans. Leurs nobles entretiennent de vieilles maisons et des querelles plus vieilles encore, et leurs roturiers travaillent la terre sans guère se soucier ni des unes ni des autres. L'Église de la {link:holy-light}Lumière sacrée{/link} unit nombre d'entre eux, et ses prêtres se trouvent dans chaque village. Les humains accordent du prix aux serments, au courage et au devoir, même s'ils ne s'y tiennent pas toujours. Leur plus grand don est de rebâtir. Tout ce qui est brûlé, ils le relèvent.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les royaumes humains ne sont plus que l'ombre de leur gloire passée. Le {link:scourge}Fléau{/link} tient les ruines de {link:lordaeron}Lordaeron{/link}, et la {link:scarlet-crusade}Croisade écarlate{/link} mène sa propre guerre impitoyable dans le nord. {link:gilneas}Gilneas{/link} s'est enfermée derrière son grand mur. {link:alterac-mountains}Alterac{/link} est en ruine, et {link:stromgarde-keep}Stromgarde{/link} s'accroche à ce qui reste des {link:arathi-highlands}Hautes-terres d'Arathi{/link}. Au sud, {link:stormwind-city}Stormwind{/link} se dresse rebâtie, mais le roi {link:varian-wrynn}Varian Wrynn{/link} a disparu, et le généralissime {link:bolvar-fordragon}Bolvar Fordragon{/link} gouverne en son nom. De l'autre côté de la mer, dame {link:jaina-proudmoore}Jaina Proudmoore{/link} tient la forteresse insulaire de {link:theramore-isle}Theramore{/link}, où les humains maintiennent une paix précaire avec la {link:horde}Horde{/link}. L'humanité reste le cœur de l'{link:alliance}Alliance{/link}, et c'est un cœur qui saigne.]=],
		},
	},
})

Translate("frFR", "dwarves", {
	title = "Nains",
	aliases = { "nain" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les nains sont un peuple robuste et endurant des montagnes de Khaz Modan. Ce sont des mineurs, des forgerons, des brasseurs et des guerriers, et ils comptent parmi les meilleurs artisans du monde. Leur grande cité d'{link:ironforge}Ironforge{/link} est taillée au cœur d'une montagne. Ils combattent aux côtés des humains depuis la {link:second-war}Deuxième Guerre{/link}, et ils demeurent l'un des piliers de l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant des âges, les nains vécurent sous les montagnes, et leurs propres légendes disaient qu'ils avaient été façonnés dans la pierre. Dans les salles d'{link:uldaman}Uldaman{/link}, des érudits de la {link:explorers-league}Ligue des explorateurs{/link} ont trouvé des archives des titans qui semblent le confirmer : elles parlent des terrestres, des êtres de roche vivante créés par les titans pour façonner les lieux profonds du monde. Beaucoup de nains croient désormais que leur peuple descend d'eux.

Les nains furent longtemps unis sous un seul haut roi à {link:ironforge}Ironforge{/link}. Quand ce roi mourut, trois grands clans entrèrent en guerre pour son trône. Lors de cette guerre des Trois Marteaux, le clan Bronzebeard tint Ironforge. Le clan Wildhammer fut chassé vers le nord et finit par s'établir dans les {link:the-hinterlands}Hinterlands{/link}. Le {link:dark-iron-dwarves}clan Sombrefer{/link} fut rejeté vers le sud. Là, son roi-sorcier, {link:ruins-of-thaurissan}Thaurissan{/link}, chercha un pouvoir pour venger sa défaite, et il invoqua {red:ragnaros}Ragnaros{/red}, le seigneur du Feu. Le feu de cette invocation brisa la terre et lia les Sombrefer au service du seigneur du Feu.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les nains sont fiers, loyaux et lents à pardonner. Ils aiment la bonne bière, les chants bruyants et les haches bien faites. Ils respectent les actes plus que les paroles et sont connus pour leur longue mémoire. Leurs armuriers sont célèbres dans tous les {link:eastern-kingdoms}Royaumes de l'est{/link}, et leurs fusils et leurs canons ont tenu bien des murailles. Les Wildhammer sont plus sauvages que leurs cousins et montent des griffons au combat, tandis que les Bronzebeard préfèrent la forge et le fusil.]=],
		},
		{
			title = "De nos jours",
			text = [=[Le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} règne à {link:ironforge}Ironforge{/link}. Son frère {link:brann-bronzebeard}Brann Bronzebeard{/link} dirige la {link:explorers-league}Ligue des explorateurs{/link}, dont les fouilleurs creusent des ruines à travers le monde en quête du véritable passé des nains. Ironforge a ouvert ses portes aux {link:gnomes}gnomes{/link} qui ont perdu leur cité au profit des {link:troggs}troggs{/link}, et {link:tinker-town}Tinker Town{/link} résonne désormais du travail gnome. Les {link:dark-iron-dwarves}Nains Sombrefer{/link} restent les ennemis les plus acharnés de leurs cousins, et dans les profondeurs du {link:blackrock-mountain}Mont Blackrock{/link} ils peinent au service du seigneur du Feu. Les Wildhammer gardent leur propre conseil dans les {link:the-hinterlands}Hinterlands{/link}, alliés d'Ironforge mais jamais ses sujets.]=],
		},
	},
})

Translate("frFR", "gnomes", {
	title = "Gnomes",
	aliases = { "gnome" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les gnomes sont un peuple petit, ingénieux et d'une curiosité sans fin. Ce sont les plus grands bricoleurs et ingénieurs du monde, et ils voient un problème à résoudre dans tout ce qu'ils rencontrent. Pendant des générations, ils vécurent dans la merveilleuse cité de {link:gnomeregan}Gnomeregan{/link}, dans les montagnes de {link:dun-morogh}Dun Morogh{/link}. Cette cité est aujourd'hui perdue pour eux, et ils vivent en invités des {link:dwarves}nains{/link} à {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Les gnomes sont depuis longtemps les voisins et les amis des nains de Khaz Modan. De leurs premiers jours, les histoires d'{link:azeroth}Azeroth{/link} disent peu de choses. Ce qui est certain, c'est qu'ils bâtirent {link:gnomeregan}Gnomeregan{/link} de leurs propres mains et l'emplirent de merveilles : de grandes machines, des serviteurs mécaniques et des appareils qu'aucun autre peuple n'aurait pu imaginer. Lors de la {link:second-war}Deuxième Guerre{/link}, ils rejoignirent l'{link:alliance}Alliance{/link} aux côtés des nains. Ils envoyèrent peu de soldats, car ils ne sont pas un peuple nombreux, mais ils donnèrent à l'Alliance des machines volantes, des sous-marins et des armes de leur invention.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les gnomes sont vifs, rapides et joyeux, même aux heures les plus sombres. Ils sont aussi facilement distraits, et leurs inventions ne font pas toujours ce que leurs créateurs avaient prévu. Ils placent l'ingéniosité au-dessus de la force, et ils tiennent leurs maîtres ingénieurs dans le plus grand honneur. Leur chef porte le titre de Grand Artisan. Beaucoup de gnomes étudient aussi la {link:arcane-magic}magie des arcanes{/link}, et certains se tournent vers des arts plus sombres que d'autres jugent préférable de laisser de côté.]=],
		},
		{
			title = "De nos jours",
			text = [=[Après la {link:third-war}Troisième Guerre{/link}, les {link:troggs}troggs{/link} surgirent des profondeurs de la terre et se déversèrent dans {link:gnomeregan}Gnomeregan{/link}. La cité ne put être tenue. Le Grand Artisan {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} fit un choix désespéré et libéra une arme toxique pour chasser les envahisseurs. Elle tua beaucoup de troggs, mais elle tua aussi un très grand nombre de gnomes, et elle laissa la cité empoisonnée. Les survivants s'enfuirent à {link:ironforge}Ironforge{/link}. On murmure aujourd'hui que la chute ne fut pas un accident : le propre conseiller du Grand Artisan, {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}, aurait trahi son peuple, et il règne désormais sur la cité en ruine en maître fou. Les gnomes rêvent du jour où ils reprendront leur foyer. En attendant, ils bricolent à Ironforge et servent l'{link:alliance}Alliance{/link} avec le même zèle qu'ils ont toujours montré.]=],
		},
	},
})

Translate("frFR", "night-elves", {
	title = "Elfes de la nuit",
	aliases = { "kaldorei", "kal'dorei", "elfe de la nuit" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les elfes de la nuit, qui se nomment eux-mêmes les kaldorei, ou « enfants des étoiles », sont le plus ancien peuple civilisé de {link:kalimdor}Kalimdor{/link}. Ils sont grands, ont la peau violette et vivent longtemps, et ils gardent les forêts du nord depuis dix mille ans. Leurs prêtresses servent la déesse de la lune, Elune, et leurs druides veillent sur la nature selon les voies enseignées par le demi-dieu {link:cenarius}Cenarius{/link}. Après la {link:third-war}Troisième Guerre{/link}, ils rejoignirent l'{link:alliance}Alliance{/link} pour la première fois de leur histoire.]=],
		},
		{
			title = "Origines",
			text = [=[Les premiers elfes de la nuit étaient une tribu qui s'établit sur les rives du {link:well-of-eternity}puits d'Éternité{/link} dans les temps anciens. La puissance du Puits les changea et leur donna une longue vie. Sur ses rives, ils élevèrent un grand empire, gouverné par la {link:queen-azshara}reine Azshara{/link} et sa caste de sorciers Bien-nés. Les Bien-nés s'enivrèrent de la puissance du Puits, et leur magie finit par attirer l'œil de la {link:burning-legion}Légion ardente{/link}. {link:azshara}Azshara{/link} ouvrit la voie aux démons, et la {link:war-of-the-ancients}guerre des Anciens{/link} commença.

Le druide {link:malfurion-stormrage}Malfurion Stormrage{/link}, la prêtresse {link:tyrande-whisperwind}Tyrande Whisperwind{/link} et leurs alliés repoussèrent la Légion. À la fin, le Puits fut détruit, et la {link:great-sundering}Fracture{/link} brisa l'ancien continent. Les elfes de la nuit qui survécurent se détournèrent de la magie des arcanes. Sur le mont Hyjal, ils veillèrent sur un nouvel arbre de vie, {link:nordrassil}Nordrassil{/link}, qui leur accorda l'immortalité. Les Bien-nés qui refusèrent de renoncer à leur magie furent envoyés en exil de l'autre côté de la mer.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les elfes de la nuit sont un peuple patient et vigilant. Leurs femmes ont longtemps servi comme {link:sentinels}Sentinelles{/link}, les guerrières qui gardent les forêts, tandis que leurs hommes devinrent des druides qui dormirent de longues années dans le {link:emerald-dream}Rêve d'émeraude{/link}. Ils aiment les lieux sauvages du monde et haïssent ceux qui les saccagent. Ils ne font pas confiance aux arcanes, car les arcanes ont failli mettre fin à leur monde.]=],
		},
		{
			title = "De nos jours",
			text = [=[Lors de la {link:third-war}Troisième Guerre{/link}, la Légion revint. À la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, elfes de la nuit, humains et orcs se dressèrent ensemble contre {link:archimonde}Archimonde{/link}, et la puissance de {link:nordrassil}Nordrassil{/link} fut dépensée pour le détruire. Avec elle, les elfes de la nuit perdirent leur immortalité. L'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} et ses druides élevèrent alors un nouvel Arbre-Monde, {link:teldrassil}Teldrassil{/link}, au large de la côte nord, et la cité de {link:darnassus}Darnassus{/link} grandit dans ses branches. {link:tyrande-whisperwind}Tyrande{/link} y règne en tant que grande prêtresse, tandis que {link:malfurion-stormrage}Malfurion{/link} arpente le {link:emerald-dream}Rêve d'émeraude{/link} et n'est pas revenu. Les kaldorei font désormais face aux orcs qui abattent les forêts d'{link:ashenvale}Orneval{/link}, et à la corruption qui se répand dans le {link:felwood}Gangrebois{/link}.]=],
		},
	},
})

Translate("frFR", "orcs", {
	title = "Orcs",
	aliases = { "orc" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les orcs sont un fier peuple guerrier venu du monde de Draenor. Ils vinrent sur {link:azeroth}Azeroth{/link} en conquérants par la {link:dark-portal}Porte des Ténèbres{/link}, et ils apportèrent le feu et la ruine aux royaumes humains. Ils furent vaincus, emprisonnés et brisés, et pourtant ils se relevèrent. Sous leur chef de guerre {link:thrall}Thrall{/link}, ils ont traversé la mer jusqu'à {link:kalimdor}Kalimdor{/link} et bâti une nouvelle patrie en {link:durotar}Durotar{/link}. Ils sont le cœur de la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Sur Draenor, les orcs vivaient en de nombreux clans. C'étaient des chasseurs et des guerriers, guidés par des chamans qui parlaient avec les esprits des {link:elements}éléments{/link}. Le seigneur démon {link:kil-jaeden}Kil'jaeden{/link} entreprit d'en faire une arme de la {link:burning-legion}Légion ardente{/link}. Il trompa l'ancien chaman {link:ner-zhul}Ner'zhul{/link}, et après lui l'apprenti de Ner'zhul, {link:gul-dan}Gul'dan{/link}. Gul'dan enseigna aux clans les arts du démoniste, et les éléments se détournèrent des orcs. Enfin, les chefs burent le sang du démon {link:mannoroth}Mannoroth{/link}, et une soif de sang s'empara du peuple tout entier.

Par la {link:dark-portal}Porte des Ténèbres{/link}, la {link:horde}Horde{/link} s'abattit sur le royaume d'{link:azeroth}Azeroth{/link}. Elle remporta la {link:first-war}Première Guerre{/link} et incendia {link:stormwind-city}Stormwind{/link}. Sous {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, elle faillit remporter aussi la {link:second-war}Deuxième Guerre{/link}, mais elle fut trahie de l'intérieur et vaincue. Les orcs survivants furent parqués dans des camps d'internement, où une étrange léthargie s'abattit sur eux.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les orcs honorent la force, le courage et la loyauté envers le clan. Ils respectent le chaman qui parle pour les esprits et le guerrier qui tient bon au combat. Leurs noms sont fiers, et leur mémoire aussi : chaque clan garde ses propres légendes et ses propres rancunes. Depuis la fin de la malédiction du démon, beaucoup d'orcs sont revenus aux anciennes voies du chaman et cherchent l'équilibre avec les éléments.]=],
		},
		{
			title = "De nos jours",
			text = [=[Le jeune orc {link:thrall}Thrall{/link}, élevé comme esclave dans une forteresse humaine, échappa à ses maîtres et libéra son peuple des camps. À l'appel d'un prophète, il le mena vers l'ouest, jusqu'à {link:kalimdor}Kalimdor{/link}. Là, pendant la {link:third-war}Troisième Guerre{/link}, {link:grom-hellscream}Grom Hellscream{/link} tua {link:mannoroth}Mannoroth{/link} et libéra les orcs du sang du démon. Thrall nomma sa nouvelle terre {link:durotar}Durotar{/link}, d'après son père Durotan, et sa capitale {link:orgrimmar}Orgrimmar{/link}, d'après Doomhammer. Les orcs maintiennent aujourd'hui une paix précaire avec {link:theramore-isle}Theramore{/link}. Pourtant, tous les orcs ne se sont pas détournés des anciennes ténèbres. Le culte de la {link:burning-blade}Lame ardente{/link} murmure dans les grottes de Durotar, et dans les {link:eastern-kingdoms}Royaumes de l'est{/link} le {link:blackrock-clan}clan Blackrock{/link} sert encore les dragons noirs dans le {link:blackrock-mountain}Mont Blackrock{/link}.]=],
		},
	},
})

Translate("frFR", "trolls", {
	title = "Trolls",
	sections = {
		{
			title = "Résumé",
			text = [=[Les trolls comptent parmi les plus anciens peuples d'{link:azeroth}Azeroth{/link}. Ils sont grands, armés de défenses et féroces, et leur corps guérit des blessures qui tueraient n'importe quelle autre créature. Bien avant que les elfes de la nuit n'élèvent leur empire, les trolls régnaient sur de grands royaumes à eux. Ces empires sont tombés, et les tribus qui restent sont amères, divisées et dangereuses. L'une d'elles, la tribu {link:darkspear-trolls}Darkspear{/link}, se tient désormais aux côtés de la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Le plus ancien royaume troll était celui des Zandalari, dont la tribu vivait loin au sud. D'eux naquirent les deux grands empires des temps anciens : les Amani dans les forêts du nord et les Gurubashi dans les jungles du sud. Ils vénéraient de puissants esprits appelés loa, et ils firent la guerre aux premiers elfes de la nuit et la perdirent. La {link:great-sundering}Fracture{/link} déchira leurs terres.

Les Amani ne pardonnèrent jamais aux hauts-elfes qui s'établirent dans leurs forêts. Lors des {link:troll-wars}guerres des Trolls{/link}, ils faillirent détruire {link:quel-thalas}Quel'Thalas{/link}, jusqu'à ce que les humains d'{link:arathor}Arathor{/link} se joignent aux elfes et les brisent. Au sud, les Gurubashi sombrèrent dans la guerre civile quand les prêtres atal'ai invoquèrent {link:hakkar}Hakkar{/link}, le dieu du sang. Les tribus renversèrent le dieu et chassèrent les Atal'ai dans les marais, où ils bâtirent le temple d'{link:temple-of-atal-hakkar}Atal'Hakkar{/link}. Leur empire ne s'en remit jamais.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les trolls sont des chasseurs et des pillards. Leurs prêtres pratiquent le vaudou et parlent avec les loa, et leurs sorciers-docteurs préparent des potions et des maléfices que les autres peuples redoutent. Beaucoup de tribus s'en tiennent à des coutumes cruelles, et certaines, dit-on, mangent leurs ennemis. Ils sont fiers de leur passé ancien et pleins de rancœur envers les jeunes peuples qui ont pris leurs terres. Peu de trolls font confiance aux étrangers, et moins encore obtiennent leur confiance en retour.]=],
		},
		{
			title = "De nos jours",
			text = [=[La {link:darkspear-trolls}tribu Darkspear{/link} fut chassée de son foyer dans les jungles et trouva refuge dans les mers du sud. Là, {link:thrall}Thrall{/link} la sauva des humains et de la sorcière des mers, et son chef Sen'jin donna sa vie pour que son peuple puisse suivre les orcs. Aujourd'hui, les Darkspear servent la {link:horde}Horde{/link} sous {link:vol-jin}Vol'jin{/link}. Ils s'établirent sur les {link:echo-isles}Îles de l'Écho{/link}, au large du {link:durotar}Durotar{/link}, mais un sorcier-docteur nommé {link:zalazane}Zalazane{/link} s'est emparé des îles par la magie noire, et la tribu s'est retirée au {link:sen-jin-village}Village de Sen'jin{/link}, sur le continent. Ailleurs, les tribus trolls restent les ennemies de tous : les Amani dans les forêts du nord, les {link:witherbark-trolls}Witherbark{/link} et les Vilebranch dans les {link:the-hinterlands}Hinterlands{/link}, les tribus gurubashi de la {link:stranglethorn-vale}Vallée de Strangleronce{/link}, les {link:sandfury-trolls}Sandfury{/link} de {link:tanaris}Tanaris{/link} et les {link:frostmane-trolls}Frostmane{/link} de {link:dun-morogh}Dun Morogh{/link}.]=],
		},
	},
})

Translate("frFR", "tauren", {
	title = "Taurens",
	aliases = { "tauren", "shu'halo" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les taurens sont un peuple de grande stature et de douce sagesse qui parcourt les plaines de {link:kalimdor}Kalimdor{/link}. Ils sont énormes et semblables à des taureaux, et ils peuvent être terribles au combat, mais ils préfèrent vivre en paix avec la terre. Ils vénèrent la Terre-Mère par-dessus tout. Sous leur grand chef {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, ils se sont établis dans les prairies de {link:mulgore}Mulgore{/link} et ont rejoint la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Les taurens, qui se nomment eux-mêmes les shu'halo, comptent parmi les plus anciens peuples de {link:kalimdor}Kalimdor{/link}. Pendant des âges, ils errèrent dans les plaines en nomades, suivant les grands troupeaux et le cours des saisons. Ils disent que la Terre-Mère leur a donné la terre, et que le soleil et la lune sont ses yeux, qu'ils nomment An'she et Mu'sha. Les tribus vivaient séparées, chacune avec ses propres chefs et ses propres totems.

Cette vie faillit prendre fin à cause des {link:centaurs}centaures{/link}. Les cruels hommes-chevaux des plaines traquèrent les tribus dispersées pendant des générations et les chassèrent de leurs terres ancestrales. {link:cairne-bloodhoof}Cairne Bloodhoof{/link} entreprit d'unir les tribus contre eux. Quand les orcs vinrent à Kalimdor, Cairne rencontra le jeune {link:thrall}Thrall{/link}, et les deux peuples se reconnurent comme parents par l'esprit. Avec l'aide des orcs, les taurens brisèrent l'emprise des centaures sur {link:mulgore}Mulgore{/link} et en firent leur patrie.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les taurens vivent près de la terre. Ils chassent avec respect et ne prennent que ce dont ils ont besoin. Leurs chamans parlent avec les esprits des {link:elements}éléments{/link} et de leurs ancêtres, et certains taurens ont appris les voies du druide, formés par les elfes de la nuit du {link:cenarion-circle}Cercle cénarien{/link}. Ils sont patients, lents à la colère et honnêtes jusqu'à l'excès. Leurs totems conservent les lignées et les hauts faits de leurs tribus.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les taurens ont bâti leur capitale, {link:thunder-bluff}Thunder Bluff{/link}, sur de hautes mesas au-dessus de {link:mulgore}Mulgore{/link}, que l'on atteint par de grands ascenseurs. {link:cairne-bloodhoof}Cairne{/link} y règne en tant que grand chef, respecté même par ceux qui craignent la {link:horde}Horde{/link}. Toutes les tribus ne partagent pas sa vision. La {link:grimtotem-clan}tribu Totem sinistre{/link}, menée par la vieille {link:magatha-grimtotem}Magatha{/link}, nourrit ses propres ambitions, et beaucoup à Thunder Bluff ne lui font guère confiance. Autour de Mulgore, les taurens affrontent encore des ennemis : les {link:quilboar}huran{/link} de la tribu {link:bristleback-quilboar}Dos-hirsute{/link}, les harpies des crêtes et les centaures des {link:the-barrens}Tarides{/link}. Les taurens honorent leur dette envers les orcs, et ils comptent parmi les membres les plus fidèles de la Horde.]=],
		},
	},
})

Translate("frFR", "forsaken", {
	title = "Réprouvés",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Réprouvés sont des morts-vivants qui se sont affranchis de la volonté du roi-liche. Ils furent jadis le peuple de {link:lordaeron}Lordaeron{/link}. Ils moururent de la peste, se relevèrent en esclaves du {link:scourge}Fléau{/link}, puis, en une seule heure de faiblesse dans l'emprise de leur maître, retrouvèrent leur propre esprit. Ils suivent {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, la reine banshee, et ils ont bâti un sombre royaume sous les ruines de leur ancienne capitale. Pour des raisons qui leur sont propres, ils ont rejoint la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant la {link:third-war}Troisième Guerre{/link}, la peste du {link:cult-of-the-damned}culte des Damnés{/link} balaya {link:lordaeron}Lordaeron{/link}, et le prince {link:arthas-menethil}Arthas Menethil{/link} assassina son père {link:terenas-menethil}Terenas Menethil{/link} et livra le royaume au {link:scourge}Fléau{/link}. Des milliers de morts se relevèrent au service du roi-liche. Pendant un temps, ils n'eurent aucune volonté.

Puis la puissance du roi-liche vacilla, et beaucoup de morts-vivants de Lordaeron découvrirent qu'ils pouvaient de nouveau penser par eux-mêmes. {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, l'ancienne générale des forestiers de {link:quel-thalas}Quel'Thalas{/link}, avait été relevée en banshee par Arthas lui-même. Elle se libéra avec eux. Elle se retourna contre les seigneurs de l'effroi qui cherchaient à régner sur le royaume en ruine, et elle lia l'un d'eux, {link:varimathras}Varimathras{/link}, à son service. Elle nomma son peuple les Réprouvés, et elle le mena prendre pour sien les ruines de la capitale de Lordaeron.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les Réprouvés se souviennent de leur vie, mais ils ne peuvent y retourner. Leurs amis et leurs proches les craignent et les haïssent, et beaucoup d'entre eux ont appris à haïr en retour. Ils sont sombres, amers et pragmatiques. Leurs érudits poursuivent sans honte tous les arts de l'alchimie et de la nécromancie, et leurs prêtres se sont détournés de la {link:holy-light}Lumière sacrée{/link} pour l'ombre. Parmi les vivants, ils sont tolérés plutôt que dignes de confiance.]=],
		},
		{
			title = "De nos jours",
			text = [=[Sous la cité brisée de {link:lordaeron}Lordaeron{/link}, les Réprouvés ont élevé l'{link:undercity}Undercity{/link}, un dédale de salles et d'égouts bâti dans les anciennes cryptes royales. De là, {link:sylvanas-windrunner}Sylvanas{/link} règne sur les {link:tirisfal-glades}Clairières de Tirisfal{/link} et mène la guerre sur deux fronts : contre le {link:scourge}Fléau{/link} qui tient encore les {link:eastern-plaguelands}Maleterres{/link}, et contre la {link:scarlet-crusade}Croisade écarlate{/link}, qui brûle chaque mort-vivant qu'elle trouve. Leur alliance avec la {link:horde}Horde{/link} en est une de nécessité. Les orcs et les taurens les trouvent étranges et inquiétants. Les Réprouvés, de leur côté, disent peu de choses de leurs véritables desseins, et les chimistes de la {link:royal-apothecary-society}Société royale des apothicaires{/link} travaillent en secret à une nouvelle peste.]=],
		},
	},
})

Translate("frFR", "skyborne", {
	title = "Skyborne",
	aliases = { "shen'dorei" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Skyborne, qui se nomment eux-mêmes les shen'dorei, ou « peuple caché », sont des elfes qui ont vécu pendant des milliers d'années au-delà du monde lui-même. Leur foyer est {link:zephras-isle}Zephras Isle{/link}, une île qui flotte dans {link:skywall}Skywall{/link}, le plan élémentaire de l'air. Ils partagent le sang des Bien-nés, et ils sont cousins des {link:high-elves}hauts-elfes{/link} de {link:quel-thalas}Quel'Thalas{/link}. Aujourd'hui, leur royaume céleste dépérit, et une nouvelle génération de Skyborne est descendue sur {link:azeroth}Azeroth{/link} en quête de réponses.]=],
		},
		{
			title = "Origines",
			text = [=[Les Skyborne font remonter leur lignée aux Bien-nés d'Eldre'Thalas, la cité de {link:feralas}Féralas{/link} que l'on appelle aujourd'hui {red:dire-maul}Hache-tripes{/red}. Après la {link:war-of-the-ancients}guerre des Anciens{/link}, le prince {red:tortheldrin}Tortheldrin{/red} chercha à soutenir la cité par des puissances toujours plus dangereuses. Certains de son peuple avaient vu ce qu'une telle soif de pouvoir avait fait au monde, et ils se soulevèrent contre lui. Ils déjouèrent ses desseins, mais leur rébellion fut écrasée, et ils s'enfuirent par-delà la mer, la flotte du prince sur leurs talons.

Loin à l'ouest, ils arrivèrent sur une terre gouvernée par d'anciens esprits des {link:elements}éléments{/link}. Là, ils conclurent un pacte avec les {link:vanishing-of-the-wind-spirits}esprits du vent{/link}. Les esprits arrachèrent une grande partie de cette terre pour l'emporter dans le ciel et hors du monde, et ils l'ancrèrent dans {link:skywall}Skywall{/link}. Cachés de leurs poursuivants, les exilés bâtirent une petite et brillante civilisation parmi les nuages.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les longs âges passés dans {link:skywall}Skywall{/link} changèrent les shen'dorei. Ils devinrent plus légers et plus rapides que leurs ancêtres, et la magie de l'air marqua leurs cheveux, leurs yeux et leur peau. Ils vécurent aux côtés des {link:vanishing-of-the-wind-spirits}esprits du vent{/link} en élèves et en amis. Certains d'entre eux reçurent le don des esprits appelé vue céleste, le pouvoir de voir à travers le plan élémentaire. Les esprits parlaient rarement d'{link:al-akir}Al'Akir{/link}, le seigneur des Vents, maître de Skywall, et parmi les Skyborne son nom devint une chose de crainte et de silence.]=],
		},
		{
			title = "De nos jours",
			text = [=[Sans prévenir, les {link:vanishing-of-the-wind-spirits}esprits du vent{/link} disparurent. Les anciens pylônes qui maintiennent {link:zephras-isle}Zephras Isle{/link} d'un seul tenant ont commencé à faiblir, des parties de l'île sont tombées en ruine, et ses communautés sont coupées les unes des autres. Les Skyborne sont divisés sur ce qu'il faut faire.

• {b}Les {link:windshapers}Windshapers{/link}.{/b} Descendants des premiers shen'dorei à recevoir la vue céleste, ils sont les guides spirituels de l'île. Ils cherchent à apprendre ce qu'il est advenu des esprits du vent et à les rétablir. Ils ont rejoint la {link:horde}Horde{/link}.
• {b}Le {link:high-order}High Order{/link}.{/b} Descendants des magistères Bien-nés qui fuirent Eldre'Thalas, ils croient que les Skyborne se sont trop fiés à leurs protecteurs. Ils cherchent le savoir arcanique que leurs ancêtres ont perdu, afin que leur peuple puisse tenir debout par lui-même. Ils ont rejoint l'{link:alliance}Alliance{/link}.
• {b}Les {link:al-aketh}Al'Aketh{/link}.{/b} Un culte qui s'est détourné du reste des shen'dorei pour servir {link:al-akir}Al'Akir{/link}. Enhardis par l'absence des esprits, ils ont semé la peur et se sont emparés d'une grande partie de l'île.]=],
		},
	},
})

Translate("frFR", "high-elves", {
	title = "Hauts-elfes",
	aliases = { "quel'dorei", "haut-elfe" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les hauts-elfes, ou quel'dorei, sont les enfants des exilés Bien-nés qui traversèrent la mer après la {link:great-sundering}Fracture{/link}. Dans les forêts du nord de {link:lordaeron}Lordaeron{/link}, ils bâtirent le royaume de {link:quel-thalas}Quel'Thalas{/link} et sa capitale resplendissante, Lune-d'argent. Pendant des milliers d'années, ils furent les maîtres de la {link:arcane-magic}magie des arcanes{/link} dans les {link:eastern-kingdoms}Royaumes de l'est{/link}. Lors de la {link:third-war}Troisième Guerre{/link}, leur royaume fut presque détruit.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:great-sundering}Fracture{/link}, les elfes de la nuit interdirent l'usage de la magie des arcanes. Les Bien-nés qui refusèrent d'obéir, menés par {red:dath-remar-sunstrider}Dath'Remar Sunstrider{/red}, furent exilés. Ils firent voile vers l'est et, après une longue errance, arrivèrent dans les forêts du nord, où ils combattirent les {link:trolls}trolls{/link} amani pour leur nouveau foyer. Là, ils créèrent le puits de Soleil, une source de puissance arcanique qui soutenait leur peuple. Quand les Amani se soulevèrent contre eux, ils s'allièrent aux {link:humans}humains{/link} d'{link:arathor}Arathor{/link} et leur enseignèrent la magie, et ensemble ils remportèrent les {link:troll-wars}guerres des Trolls{/link}.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les hauts-elfes sont gracieux, fiers et savants. Ils aiment la beauté et la magie, et beaucoup d'entre eux regardent de haut les jeunes peuples. Leurs forestiers sont les meilleurs archers du nord. Leur lien avec le puits de Soleil était si profond qu'ils en vinrent à dépendre de sa puissance.]=],
		},
		{
			title = "De nos jours",
			text = [=[Pendant la {link:third-war}Troisième Guerre{/link}, {link:arthas-menethil}Arthas Menethil{/link} mena le {link:scourge}Fléau{/link} en {link:quel-thalas}Quel'Thalas{/link}. Il tua le roi Anasterian Sunstrider et se servit du puits de Soleil pour relever la liche {link:kel-thuzad}Kel'Thuzad{/link}. La générale des forestiers {link:sylvanas-windrunner}Sylvanas Windrunner{/link} tomba en défendant sa patrie. Les rares survivants restent dispersés : certains tiennent encore ce qui reste de Quel'Thalas, certains servent l'{link:alliance}Alliance{/link} et le {link:kirin-tor}Kirin Tor{/link}, et une petite troupe tient le {link:quel-danil-lodge}Gîte de Quel'Danil{/link} dans les {link:the-hinterlands}Hinterlands{/link}. Le prince Kael'thas, héritier des Sunstrider, rassembla nombre des survivants et les renomma sin'dorei, les elfes de sang, en mémoire des morts. Ce qu'il est devenu depuis, aucune chronique de ces terres ne saurait le dire.]=],
		},
	},
})

Translate("frFR", "kobolds", {
	title = "Kobolds",
	aliases = { "kobold" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les kobolds sont de petites créatures semblables à des rats qui vivent dans les mines et les cavernes à travers {link:azeroth}Azeroth{/link}. Ils sont lâches, avides et pas très malins, mais ils sont très nombreux. Partout où une vieille mine est laissée sans garde, les kobolds s'installent. Chacun porte une bougie sur la tête pour éclairer les tunnels, et chacun préférerait mourir plutôt que d'y renoncer.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte d'où vinrent d'abord les kobolds. Certains fouilleurs de la {link:explorers-league}Ligue des explorateurs{/link} croient qu'ils sont issus des {link:troggs}troggs{/link} des lieux profonds. Quels que soient leurs débuts, ils étaient déjà une nuisance pour les premiers colons de {link:tirisfal-glades}Tirisfal{/link}, et ils tourmentent les mineurs depuis lors.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les kobolds aiment les tunnels sombres mais craignent la véritable obscurité, et leurs bougies sont les biens les plus précieux qu'ils possèdent. En voler une est le pire des crimes, et le voleur en entendra parler. Ils creusent sans fin et amassent tout ce qui brille. Leurs géomanciens pratiquent une magie grossière du feu et de la pierre. La plupart se contentent de ne combattre que lorsqu'ils sont acculés, mais en essaim, ils peuvent submerger un mineur imprudent.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les kobolds infestent les mines de la {link:elwynn-forest}Forêt d'Elwynn{/link} et de la {link:westfall}Marche de l'Ouest{/link}, où ils creusent pour un or qui ne reste pas entre leurs mains. On dit qu'ils sont menés par les {link:riverpaw-gnolls}gnolls Rivepatte{/link}, qui traitent à leur tour avec la {link:defias-brotherhood}Confrérie défias{/link}. Les Tunnel Rat tourmentent les nains du {link:loch-modan}Loch Modan{/link}, et à {link:kalimdor}Kalimdor{/link}, des kobolds creusent pour {link:venture-company}la KapitalRisk{/link} dans les {link:stonetalon-mountains}Serres-Rocheuses{/link}.]=],
		},
	},
})

Translate("frFR", "gnolls", {
	title = "Gnolls",
	aliases = { "gnoll" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les gnolls sont des créatures semblables à des hyènes qui parcourent les lieux sauvages des {link:eastern-kingdoms}Royaumes de l'est{/link} et de {link:kalimdor}Kalimdor{/link}. Ils sont brutaux, querelleurs et affamés, et ils placent la force au-dessus de tout. Ils vivent en meutes et en clans, chacun gouverné par le plus fort d'entre eux, et ils pillent les fermes et les routes des autres peuples pour se nourrir et faire du butin.]=],
		},
		{
			title = "Origines",
			text = [=[Les gnolls sont un ancien peuple d'{link:azeroth}Azeroth{/link}, et aucune chronique ne rapporte leurs débuts. Ils comptaient parmi les dangers qu'affrontèrent les premiers colons humains dans le nord. Le royaume de {link:stormwind-city}Stormwind{/link} se souvient d'une époque plus sombre, quand un seigneur de meute des {link:redridge-gnolls}gnolls des Carmines{/link} nommé Garfang rassembla les clans en une grande armée et frappa les fermes du royaume. Le roi Barathen Wrynn partit à cheval et le tua, et les meutes s'entre-déchirèrent dans la lutte qui suivit.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les gnolls préfèrent laisser les autres faire leur travail. Leurs chefs poussent les faibles devant eux, et ils servent volontiers tout maître plus fort qui leur promet nourriture et butin. Leurs mystiques pratiquent un chamanisme grossier. Ils sont assez rusés pour tendre des pièges et des embuscades, et assez cruels pour y prendre plaisir.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les gnolls troublent presque chaque frontière des terres humaines. Les {link:riverpaw-gnolls}Rivepatte{/link} pillent la {link:elwynn-forest}Forêt d'Elwynn{/link} et la {link:westfall}Marche de l'Ouest{/link}. La {link:redridge-gnolls}meute des Carmines{/link} et les {link:shadowhide-gnolls}Sombrepoil{/link} rôdent dans les {link:redridge-mountains}Carmines{/link}, ces derniers asservis au démoniste {link:morganth}Morganth{/link}. Les Poils-moussus hantent les {link:wetlands}Paluns{/link}, les Rot Hide déterrent les morts des {link:tirisfal-glades}Clairières de Tirisfal{/link} pour le {link:scourge}Fléau{/link}, et d'autres clans parcourent les collines des {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link} et les forêts de {link:feralas}Féralas{/link}.]=],
		},
	},
})

Translate("frFR", "riverpaw-gnolls", {
	title = "Gnolls Rivepatte",
	aliases = { "gnolls Rivepatte", "Rivepatte" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Rivepatte sont le clan {link:gnolls}gnoll{/link} qui tourmente les terres du sud du {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Ils parcourent la frontière de la {link:elwynn-forest}Forêt d'Elwynn{/link}, les champs de la {link:westfall}Marche de l'Ouest{/link} et les abords des {link:redridge-mountains}Carmines{/link}. Ils pillent les fermes, tendent des embuscades aux voyageurs et combattent les rares soldats que le royaume peut épargner. Le plus redouté d'entre eux est le grand gnoll {link:hogger}Hogger{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[Les Rivepatte se sont enhardis depuis que l'armée du royaume a été envoyée au loin. Ils sortent de La Lisière pour frapper les fermes du sud d'{link:elwynn-forest}Elwynn{/link}, et la {link:westbrook-garrison}Garnison du ruisseau de l'ouest{/link} paie une prime pour chaque patte que ses volontaires rapportent. Dans la {link:westfall}Marche de l'Ouest{/link}, leurs camps sont plus grands encore. La Milice populaire a trouvé des signes que les Rivepatte ne combattent pas pour eux seuls : ils mènent des esclaves {link:kobolds}kobolds{/link} dans les mines, et ils traitent avec la {link:defias-brotherhood}Confrérie défias{/link}. Beaucoup à {link:stormwind-city}Stormwind{/link} se demandent qui les arme, et qui leur donne leur ruse inhabituelle.]=],
		},
	},
})

Translate("frFR", "murlocs", {
	title = "Murlocs",
	aliases = { "murloc" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les murlocs sont de petites créatures semblables à des poissons qui vivent le long des côtes, des lacs et des rivières d'{link:azeroth}Azeroth{/link}. Ils marchent sur deux jambes, parlent une langue gargouillante qu'aucun autre peuple ne comprend, et attaquent en essaims soudains. Chaque pêcheur des {link:eastern-kingdoms}Royaumes de l'est{/link} et de {link:kalimdor}Kalimdor{/link} a une histoire de murlocs à raconter.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte d'où viennent les murlocs. Ils hantent les rivages du monde depuis que les peuples tiennent des archives, et ils semblent ne se soucier en rien des guerres des habitants de la terre ferme.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les murlocs vivent en tribus, dans des villages de huttes bâties au bord de l'eau. Ils chassent le poisson et tout ce qui s'égare près de leurs rives. Leurs oracles et leurs chasseurs des marées manient une magie simple de l'eau et de l'orage. Ils sont rarement dangereux seuls, mais ils viennent rarement seuls. Quand un murloc est attaqué, d'autres surgissent des hauts-fonds avec un cri terrible.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les murlocs se sont enhardis à mesure que les royaumes s'affaiblissent. Ils pillent les rives des lacs de la {link:elwynn-forest}Forêt d'Elwynn{/link} et la côte de la {link:westfall}Marche de l'Ouest{/link}. La tribu des Branchies-bleues hante les marais des {link:wetlands}Paluns{/link}, et la tribu Greymist les rivages de {link:darkshore}Sombrivage{/link}. Sur chaque côte, de la {link:stranglethorn-vale}Vallée de Strangleronce{/link} au {link:durotar}Durotar{/link}, leurs huttes se dressent au bord de l'eau.]=],
		},
	},
})

Translate("frFR", "quilboar", {
	title = "Huran",
	aliases = { "huran" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les huran sont un peuple sauvage d'hommes-sangliers qui vivent dans le sud des {link:the-barrens}Tarides{/link} et les terres alentour. Ils sont couverts de soies et d'épines, et ils établissent leurs demeures parmi de grandes lianes épineuses enchevêtrées. Ils sont hostiles à presque tous les autres peuples, et ils sont depuis longtemps en guerre contre les {link:tauren}taurens{/link} et les orcs.]=],
		},
		{
			title = "Origines",
			text = [=[Les huran affirment être les enfants d'Agamaggan, le grand demi-dieu sanglier. Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, Agamaggan combattit la {link:burning-legion}Légion ardente{/link} et fut tué. Là où son sang tomba, d'immenses lianes épineuses jaillirent de la terre. Ces épines devinrent Tranchebauge, et les huran en firent leur foyer sacré.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les huran sont féroces et attachés à leur territoire. Leurs tribus sont menées par des seigneurs de guerre, et leurs géomanciens en appellent à la terre. Ils vénèrent la mémoire d'Agamaggan et tiennent Tranchebauge pour sacrée. Certaines de leurs prêtresses se sont tournées vers des arts plus sombres, et certains de leurs guerriers vers des maîtres plus sombres.]=],
		},
		{
			title = "De nos jours",
			text = [=[La {link:razormane-quilboar}tribu Tranchecrin{/link} pille les abords du {link:durotar}Durotar{/link} et le nord des {link:the-barrens}Tarides{/link}, et la tribu {link:bristleback-quilboar}Dos-hirsute{/link} trouble les plaines de {link:mulgore}Mulgore{/link}. Au sud, les huran vivent dans les grandes garennes d'épines du {link:razorfen-kraul}Kraal de Tranchebauge{/link} et des {link:razorfen-downs}Souilles de Tranchebauge{/link}. On dit que dans les Souilles, un culte appelé Death's Head s'est tourné vers le {link:scourge}Fléau{/link}, et qu'une liche vit désormais parmi eux.]=],
		},
	},
})

Translate("frFR", "centaurs", {
	title = "Centaures",
	aliases = { "centaure" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les centaures sont un peuple cruel et belliqueux de {link:kalimdor}Kalimdor{/link}. Ils ont le haut du corps d'un homme et le corps d'un cheval, et ce sont de terribles pillards qui chevauchent en bandes rapides et impitoyables. Depuis des générations, ils sont les plus grands ennemis des {link:tauren}taurens{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[On dit que les centaures descendent de l'union de Zaetar, un fils du demi-dieu {link:cenarius}Cenarius{/link}, et de Theradras, une princesse de la terre élémentaire. Leurs premiers enfants étaient cruels au-delà de toute mesure, et dans un accès de jalousie, ils tuèrent leur propre père. Theradras déposa Zaetar pour son dernier repos dans les cavernes de {red:maraudon}Maraudon{/red}, où son esprit s'attarderait encore, dit-on.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les centaures vivent en nomades et en pillards. Ils estiment que le fort doit prendre au faible ce qu'il veut. Leurs khans mènent les tribus, et les tribus se font la guerre entre elles quand elles n'ont pas d'autres ennemis. Ce sont d'habiles cavaliers et archers, et ils montrent peu de pitié.]=],
		},
		{
			title = "De nos jours",
			text = [=[La tribu {link:kolkar-centaurs}Kolkar{/link} parcourt les {link:the-barrens}Tarides{/link}, et ses pillards frappent les avant-postes orcs de la région. Les Galak chevauchent à travers {link:thousand-needles}Mille pointes{/link}. En {link:desolace}Désolace{/link}, les Magram et les Gelkis mènent une longue querelle, et tous deux revendiquent la faveur de Theradras. Les Maraudine gardent l'entrée de Maraudon même. Bien que {link:cairne-bloodhoof}Cairne{/link} ait chassé les centaures de {link:mulgore}Mulgore{/link}, ils n'ont pas oublié les taurens.]=],
		},
	},
})

Translate("frFR", "furbolgs", {
	title = "Furbolgs",
	aliases = { "furbolg" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les furbolgs sont un peuple semblable à des ours qui vit dans les forêts du nord de {link:kalimdor}Kalimdor{/link}. Ils furent longtemps un peuple doux et paisible, amis des {link:night-elves}elfes de la nuit{/link} et des druides. Ces dernières années, une maladie de l'esprit s'est abattue sur la plupart de leurs tribus, et beaucoup de furbolgs sont devenus sauvages et hostiles.]=],
		},
		{
			title = "Origines",
			text = [=[Les furbolgs vivent dans les forêts de {link:kalimdor}Kalimdor{/link} depuis les temps anciens. Ils comptaient jadis parmi les alliés des {link:night-elves}kaldorei{/link}. Aucune chronique ne rapporte leurs débuts plus en détail.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les furbolgs vivent en tribus, dans des tanières et des villages cachés au fond des bois. Leurs chamans connaissent bien les voies de la forêt. La plupart se contentaient de vivre tranquillement et de commercer en paix avec leurs voisins.]=],
		},
		{
			title = "De nos jours",
			text = [=[La souillure démoniaque laissée dans les forêts depuis la {link:third-war}Troisième Guerre{/link} a rendu fous beaucoup de tribus. Les {link:thistlefur-village}Crins-de-Chardon{/link} et les Foulweald d'{link:ashenvale}Orneval{/link}, les {link:deadwood-furbolgs}Mort-bois{/link} du {link:felwood}Gangrebois{/link}, les {link:blackwood-furbolgs}Noirbois{/link} de {link:darkshore}Sombrivage{/link}, les {link:gnarlpine-furbolgs}Pins-tordus{/link} de {link:teldrassil}Teldrassil{/link} et les {link:winterfall-furbolgs}Tombe-hiver{/link} du {link:winterspring}Berceau-de-l'Hiver{/link} se sont retournés contre leurs anciens amis. Seuls les {link:timbermaw-furbolgs}Grumegueules{/link} ont résisté à la corruption. Ils gardent les cols du Repaire des Grumegueules et ne font confiance à aucun étranger tant qu'il n'a pas fait ses preuves.]=],
		},
	},
})

Translate("frFR", "harpies", {
	title = "Harpies",
	aliases = { "harpie" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les harpies sont des créatures ailées de {link:kalimdor}Kalimdor{/link}, au corps de femme et aux ailes et aux serres d'oiseau. Elles sont cruelles, rusées et vicieuses, et elles s'en prennent aux voyageurs depuis leurs nids dans les hauteurs.]=],
		},
		{
			title = "Origines",
			text = [=[Les origines des harpies ne sont consignées dans aucune chronique connue de ce registre.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les harpies vivent en volées gouvernées par des matriarches. Elles nichent sur les falaises et les crêtes et fondent sur tout ce qui est plus faible qu'elles. Elles aiment les objets brillants volés et la chair de ceux qu'elles attrapent. Leurs sorcières commandent une magie noire.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les {link:windfury-harpies}harpies Furies-des-vents{/link} nichent sur les crêtes de {link:mulgore}Mulgore{/link}, au grand agacement des taurens. Les Witchwing se perchent dans les {link:the-barrens}Tarides{/link}, les Bloodfury dans les {link:stonetalon-mountains}Serres-Rocheuses{/link}, et les Northspring à {link:feralas}Féralas{/link}. Les routes de {link:kalimdor}Kalimdor{/link} ne sont pas sûres sous leurs nids.]=],
		},
	},
})

Translate("frFR", "troggs", {
	title = "Troggs",
	aliases = { "trogg" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les troggs sont des créatures brutales à la peau de pierre qui vivent loin sous la terre. Ils sont forts, stupides et d'une agressivité sans fin. Pendant des âges, ils restèrent cachés dans les profondeurs. Ils sont désormais remontés à la surface, et ils ont apporté la ruine avec eux.]=],
		},
		{
			title = "Origines",
			text = [=[Les archives d'{link:uldaman}Uldaman{/link} racontent que les troggs furent créés par les titans, comme les terrestres. C'était une création imparfaite, et les titans les scellèrent dans les caveaux profonds du monde. La {link:explorers-league}Ligue des explorateurs{/link} croit que les nains ont troublé ces caveaux en creusant à Uldaman, et que les troggs se répandent depuis lors.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les troggs vivent en tribus menées par le plus fort d'entre eux. Leurs chamans manient une magie grossière de la terre. Ils ne se soucient guère que de se battre et de manger.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les troggs surgirent sous {link:gnomeregan}Gnomeregan{/link} et chassèrent les gnomes de leur cité. Ils combattent les nains en {link:dun-morogh}Dun Morogh{/link} et au {link:loch-modan}Loch Modan{/link}, et ils grouillent dans {link:uldaman}Uldaman{/link} et les {link:badlands}Terres ingrates{/link}. Partout où les nains creusent profond, ils craignent d'en trouver davantage.]=],
		},
	},
})

Translate("frFR", "ogres", {
	title = "Ogres",
	aliases = { "ogre" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les ogres sont des brutes énormes, à l'esprit lent et d'une grande force. Certains ont deux têtes, et quelques-uns sont de rusés sorciers. La plupart vinrent sur {link:azeroth}Azeroth{/link} avec les orcs depuis Draenor, et de nombreux clans vivent aujourd'hui dans les lieux sauvages des deux continents.]=],
		},
		{
			title = "Origines",
			text = [=[Les ogres servirent la {link:horde}Horde{/link} orque pendant la {link:second-war}Deuxième Guerre{/link}. Le démoniste {link:gul-dan}Gul'dan{/link} donna à certains d'entre eux le don de la magie, et ces mages ogres devinrent redoutés dans tous les {link:eastern-kingdoms}Royaumes de l'est{/link}. Le plus grand d'entre eux, Cho'gall, mena le clan du {link:twilight-s-hammer}Marteau du crépuscule{/link}. Après la défaite de la Horde, les clans ogres se dispersèrent dans les collines et les montagnes.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les ogres sont belliqueux et avides. Ils ne respectent que la force et se battent entre eux pour la direction du clan. Leurs chefs règnent par la massue, et leurs mages par la peur.]=],
		},
		{
			title = "De nos jours",
			text = [=[Des clans ogres tiennent les collines des {link:redridge-mountains}Carmines{/link}, de la {link:stranglethorn-vale}Vallée de Strangleronce{/link}, des {link:alterac-mountains}Montagnes d'Alterac{/link} et des {link:arathi-highlands}Hautes-terres d'Arathi{/link}. À {link:kalimdor}Kalimdor{/link}, les Gordunni hantent {link:feralas}Féralas{/link}, et les Gordok règnent sur les ruines de {red:dire-maul}Hache-tripes{/red}. Dans le {link:dustwallow-marsh}Marécage d'Âprefange{/link}, le clan Cognepierres a perdu son ancienne force, et certains de ses ogres vivent désormais aux côtés des orcs.]=],
		},
	},
})

Translate("frFR", "naga", {
	title = "Nagas",
	aliases = { "naga" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les nagas sont des créatures serpentines des mers profondes. Ils furent jadis des elfes de la nuit de la caste des Bien-nés. Ils ont aujourd'hui des queues écailleuses et des visages cruels, et ils sont revenus des profondeurs pour troubler les rivages du monde.]=],
		},
		{
			title = "Origines",
			text = [=[Quand le {link:well-of-eternity}puits d'Éternité{/link} fut détruit lors de la {link:great-sundering}Fracture{/link}, le palais de la {link:queen-azshara}reine Azshara{/link} fut englouti par la mer avec toute sa cour. Quelque chose dans les profondeurs les sauva, et les changea. Les Bien-nés noyés devinrent les nagas. Pendant dix mille ans, ils vécurent cachés sous les vagues. Au temps de la {link:third-war}Troisième Guerre{/link}, ils resurgirent, et ils servirent {link:illidan-stormrage}Illidan Stormrage{/link} pendant un temps.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les nagas sont fiers, amers et ambitieux. Leurs sirènes sont de puissantes sorcières qui commandent les eaux et les tempêtes. Leurs myrmidons sont de redoutables guerriers. On dit qu'ils honorent encore {link:azshara}Azshara{/link} dans les profondeurs.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les nagas ont revendiqué des portions de côte en {link:azshara}Azshara{/link}, à {link:darkshore}Sombrivage{/link}, en {link:ashenvale}Orneval{/link} et en {link:desolace}Désolace{/link}. Ils hantent le temple inondé des {link:blackfathom-deeps}Profondeurs de Brassenoire{/link}. Ce qu'ils cherchent sur les rivages de {link:kalimdor}Kalimdor{/link}, les elfes de la nuit l'ignorent.]=],
		},
	},
})

Translate("frFR", "satyrs", {
	title = "Satyres",
	aliases = { "satyre" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les satyres sont des démons de la forêt, cornus et aux pattes de bouc. Ils furent jadis des elfes de la nuit Bien-nés qui se vendirent à la {link:burning-legion}Légion ardente{/link}. Ils hantent aujourd'hui les bois corrompus du nord de {link:kalimdor}Kalimdor{/link}, répandant la souillure de la {link:fel-magic}magie gangrenée{/link} partout où ils vont.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, le seigneur Xavius, conseiller de la {link:queen-azshara}reine Azshara{/link}, fut le premier des Bien-nés à servir les démons. Après sa défaite, le maître de la Légion le refaçonna en premier satyre. Xavius, à son tour, conduisit beaucoup de Bien-nés au même sort. Les satyres combattirent pour la Légion tout au long de la guerre, et beaucoup survécurent à la {link:great-sundering}Fracture{/link}.]=],
		},
		{
			title = "Nature et coutumes",
			text = [=[Les satyres sont cruels, fourbes et avides de pouvoir. Ils servent les démons, que la Légion soit proche ou lointaine. Leur magie est gangrenée, et ils corrompent la terre où ils vivent. Leurs tribus vivent dans de sombres bosquets au sein des forêts qu'ils saccagent.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les satyres se sont répandus dans les forêts depuis la {link:third-war}Troisième Guerre{/link}. Ils infestent le {link:felwood}Gangrebois{/link} et {link:ashenvale}Orneval{/link}, où le {link:satyrnaar}Satyrnaar{/link} est leur place forte, et ils rôdent dans les ruines d'{link:azshara}Azshara{/link} et dans les profondeurs de {red:dire-maul}Hache-tripes{/red}. Les {link:sentinels}Sentinelles{/link} les traquent sans pitié.]=],
		},
	},
})
